    def reset(self) -> None:
        self.sim_steps += self.ep.steps
        self.ep.close()
        self.ep = Episode(self.instance)
        self.resets += 1
        self._log({"ev": "reset"})

    def step(self, row) -> bool:
        return self.ep.step(row)

